// ===== CẤU HÌNH: sửa ba giá trị này =====
return [{
  json: {
    web_app_url: 'DAN_URL_WEB_APP_VAO_DAY',
    notify_to: 'DAN_EMAIL_NHOM_VAO_DAY',
    from_email: 'DAN_GMAIL_GUI_VAO_DAY',
  },
}];

// Soạn email từ phản hồi của Apps Script. Không có gì để báo thì dừng ở đây.
// Khuôn: tiêu đề nói số việc, dòng đầu chỉ nêu điều cần làm ngay, việc cần làm ghi trên dòng của từng đơn.
const data = $input.first().json;
const cfg = $('Cấu hình').first().json;
if (data.ok !== true) {
  throw new Error('Apps Script không trả danh sách đơn: ' + (data.error_code || 'phản hồi lạ'));
}

const unit = data.unit_label || 'phần';
const money = (v) => String(v).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'đ';
const SOURCE = { landing: 'trang bán hàng', messenger: 'Messenger', backup: 'form dự phòng' };
const ZONE = { trong_2km: 'trong 2km', den_10km: 'đến 10km' };
const STATUS = { dang_lam: 'Đang làm', dang_giao: 'Đang giao', xong: 'Xong', huy: 'Huỷ', bom: 'Bom' };
const sentence = (text) => {
  const clean = String(text || '').trim().replace(/[.]+$/, '');
  return clean ? clean.charAt(0).toLowerCase() + clean.slice(1) : '';
};

// created_at là 'yyyy-MM-dd HH:mm:ss' giờ Việt Nam. Đơn không phải hôm nay (báo muộn sau khi máy tắt qua đêm) ghi cả ngày.
const todayVn = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 10);
const when = (createdAt) => {
  const text = String(createdAt);
  const time = text.slice(11, 16);
  if (!/^\d{4}-\d{2}-\d{2} /.test(text) || text.slice(0, 10) === todayVn) return time;
  return text.slice(8, 10) + '/' + text.slice(5, 7) + ' ' + time;
};

const orderText = (o) => {
  const head = [o.order_code, o.cups + ' ' + unit, money(o.total)];
  if (o.needs_call) head.push('CẦN GỌI' + (o.call_reason ? ': ' + o.call_reason : ' trước khi làm'));
  if (o.payment_status === 'cho_chuyen_khoan') head.push('Chờ chuyển khoản');
  if (o.payment_status === 'da_nhan') head.push('Đã nhận tiền');
  if (STATUS[o.status]) head.push('Trạng thái: ' + STATUS[o.status]);
  const lines = [
    head.join(' · '),
    '  ' + o.name + ' · ' + o.phone + ' · ' + (o.delivery_method === 'giao' ? 'Giao ' + (ZONE[o.zone] || o.zone) : 'Tự đến lấy'),
  ];
  if (o.delivery_method === 'giao' && o.address) lines.push('  ' + o.address);
  lines.push('  ' + o.items_text);
  if (o.note) lines.push('  Ghi chú: ' + o.note);
  if (o.contact) lines.push('  Liên hệ: ' + o.contact);
  lines.push('  Qua ' + (SOURCE[o.source] || o.source) + ' lúc ' + when(o.created_at));
  return lines.join('\n');
};

const orders = data.orders || [];
const low = data.low_stock || {};
const configAlert = data.config_alert || {};
const backupErrors = data.backup_errors || [];
const emails = [];

if (configAlert.alert === true) {
  emails.push({
    subject: '⚠️ Tab Cấu hình đang có ô sai',
    text: (configAlert.messages || []).join('\n') + '\nVẫn nhận đơn bình thường.',
  });
}

if (low.alert === true) {
  emails.push({
    subject: '⚠️ Còn ' + low.remaining_cups + ' ' + unit + ' cuối',
    text: 'Đã nhận ' + low.counted_cups + '/' + low.max_cups + ' ' + unit + '.',
  });
}

if (orders.length > 0) {
  const cups = orders.reduce((sum, o) => sum + o.cups, 0);
  const calls = orders.filter((o) => o.needs_call).length;
  const subject = ['🔔 ' + orders.length + ' đơn mới', cups + ' ' + unit];
  if (calls) subject.push(calls + ' cần gọi');
  const blocks = orders.map(orderText);
  if (calls) blocks.unshift('Có ' + orders.length + ' đơn mới, ' + calls + ' đơn cần gọi trước khi làm.');
  emails.push({ subject: subject.join(' · '), text: blocks.join('\n\n') });
}

if (backupErrors.length > 0) {
  emails.push({
    subject: '⚠️ ' + backupErrors.length + ' đơn từ form dự phòng chưa nhận được',
    text: backupErrors
      .map((e) => {
        const who = (e.name || 'khách') + (e.phone ? ' (' + e.phone + ')' : '');
        return [
          'Đơn của ' + who + ' chưa vào hệ thống: ' + sentence(e.message) + '.',
          '  Gửi lúc ' + e.created_at,
          '  Khách gửi: ' + e.answers,
        ].join('\n');
      })
      .join('\n\n'),
  });
}

// ack đi cùng email: chỉ đánh dấu đúng những gì đã gửi.
const ack = {
  codes: orders.map((o) => o.order_code),
  low_stock: low.alert === true,
  backup_errors: backupErrors.map((e) => e.response_id),
};
if (configAlert.alert === true) ack.config_alert = configAlert.signature;
return emails.map((email) => ({
  json: { ...email, to: cfg.notify_to, from: cfg.from_email, ack },
}));

// Ack lỗi thì để execution đỏ cho dễ thấy; phút sau đơn được báo lại, không mất.
const data = $input.first().json;
if (data.ok !== true) {
  throw new Error('Apps Script không nhận ack: ' + (data.error_code || 'phản hồi lạ'));
}
return [{ json: { acked: data.acked } }];
